/* DAA Lab 03 Q6 - SVG showing identical comparison growth across input orders. */
#include <stdio.h>
#define MAXP 128

typedef struct{double n,s,r,x,e,ss,rs,xs;}Row;
static double X(double n,double maxn){return 100+n/maxn*1000;}static double Y(double y,double ymax){return 610-y/ymax*460;}
int main(void){FILE*in=fopen("q6_experimental_data.dat","r");if(!in){puts("Run q6_experimental_validation first.");return 1;}Row a[MAXP];int k=0;char z[256];while(fgets(z,sizeof z,in)&&k<MAXP){if(z[0]=='#')continue;if(sscanf(z,"%lf %lf %lf %lf %lf %lf %lf %lf",&a[k].n,&a[k].s,&a[k].r,&a[k].x,&a[k].e,&a[k].ss,&a[k].rs,&a[k].xs)==8)k++;}fclose(in);if(k<2)return 1;double maxn=a[k-1].n,ymax=a[k-1].e*1.05;FILE*o=fopen("q6_selection_sort_complexity.svg","w");if(!o)return 1;
 fprintf(o,"<svg xmlns='http://www.w3.org/2000/svg' width='1200' height='700'><defs><linearGradient id='g' x1='0' x2='1'><stop stop-color='#172554'/><stop offset='1' stop-color='#0f172a'/></linearGradient></defs><rect width='1200' height='700' rx='24' fill='url(#g)'/><text x='600' y='58' fill='white' font-family='Arial' font-size='30' font-weight='700' text-anchor='middle'>Selection Sort: Best Case = Worst Case = Theta(n^2)</text><text x='600' y='90' fill='#bfdbfe' font-family='Arial' font-size='16' text-anchor='middle'>Sorted, reverse, and random inputs perform the same n(n-1)/2 key comparisons</text><line x1='100' y1='610' x2='1100' y2='610' stroke='#64748b' stroke-width='2'/><line x1='100' y1='150' x2='100' y2='610' stroke='#64748b' stroke-width='2'/>");
 const char*col[3]={"#38bdf8","#f472b6","#facc15"};for(int series=0;series<3;series++){fprintf(o,"<polyline fill='none' stroke='%s' stroke-width='%d' %s points='",col[series],series==2?3:5,series==2?"stroke-dasharray='9 7'":"");for(int i=0;i<k;i++){double v=series==0?a[i].s:series==1?a[i].r:a[i].x;fprintf(o,"%.2f,%.2f ",X(a[i].n,maxn),Y(v,ymax));}fprintf(o,"'/>");}
 fprintf(o,"<rect x='755' y='110' width='330' height='108' rx='14' fill='#0f172a' stroke='#475569'/><line x1='780' y1='139' x2='830' y2='139' stroke='#38bdf8' stroke-width='5'/><text x='845' y='145' fill='white' font-family='Arial' font-size='15'>Already sorted</text><line x1='780' y1='169' x2='830' y2='169' stroke='#f472b6' stroke-width='5'/><text x='845' y='175' fill='white' font-family='Arial' font-size='15'>Reverse sorted</text><line x1='780' y1='199' x2='830' y2='199' stroke='#facc15' stroke-width='3' stroke-dasharray='9 7'/><text x='845' y='205' fill='white' font-family='Arial' font-size='15'>Random</text><text x='600' y='660' fill='#bfdbfe' font-family='Arial' font-size='16' text-anchor='middle'>Selection sort always scans the complete unsorted suffix, regardless of its order.</text></svg>");fclose(o);puts("Created q6_selection_sort_complexity.svg");return 0;}
